import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import "./BookingHistoryPage.css";

function BookingHistoryPage() {
  const navigate = useNavigate();
  const [bookingHistory, setBookingHistory] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const userId = localStorage.getItem("userId");

    // Get all bookings from localStorage
    const allBookings = JSON.parse(localStorage.getItem("bookings")) || [];

    // Filter bookings for this user
    const userBookings = allBookings.filter(b => String(b.userId) === String(userId));

    setBookingHistory(userBookings);
    setLoading(false);
  }, []);

  return (
    <div className="history-container">
      <h1>My Booking History</h1>
      <button className="back-btn" onClick={() => navigate("/home")}>Back to Home</button>

      {loading ? (
        <p>Loading booking history...</p>
      ) : bookingHistory.length === 0 ? (
        <p>No booking history found.</p>
      ) : (
        <table>
          <thead>
            <tr>
              <th>Slot</th>
              <th>Vehicle Type</th>
              <th>Vehicle No</th>
              <th>Date</th>
              <th>Time</th>
              <th>Duration</th>
              <th>Contact</th>
            </tr>
          </thead>
          <tbody>
            {bookingHistory.map((booking, index) => (
              <tr key={index}>
                <td>{booking.slotNumber}</td>
                <td>{booking.vehicleType}</td>
                <td>{booking.vehicleNo}</td>
                <td>{booking.date}</td>
                <td>{booking.time}</td>
                <td>{booking.duration}</td>
                <td>{booking.contact || "-"}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

export default BookingHistoryPage;
